# Icon design — single source of truth. The SVG below is served at /icon.svg
# (browser favicon points at it) and is also the design that the apple-touch-icon
# PNG below is rasterized from. Update both together when the design changes.
_ICON_SVG = (
    b'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">'
    b'<rect x="0" y="0" width="512" height="512" fill="#000000"/>'
    b'<rect x="176" y="90" width="160" height="333" rx="28" fill="#FFFFFF"/>'
    b"</svg>"
)

# iOS "Add to Home Screen" icon. PNG, not SVG: data-URI SVG and real-URL SVG
# were both tested and iOS Safari refused to display either as the home-screen
# tile. PNG is what Apple's docs actually specify. 180×180 grayscale, generated
# offline via stdlib zlib+struct — 234 raw bytes — see commit history for the
# generator. The base64 below decodes to the PNG bytes at server start.
_APPLE_TOUCH_ICON_PNG = base64.b64decode(
    b"iVBORw0KGgoAAAANSUhEUgAAALQAAAC0CAAAAAAYplnuAAABF0lEQVR42u3cIU4DYRCG4SYVFQgEogJR0QMg"
    b"ERXIlRwAgUQgET0GR6hA9ggViB4AWVlZgURUDnCD3T9pZid53hM8mWTsN5lIkiRJkiRJkvTXvHvu09P91VjE"
    b"09ev6Nt5+zAK890hBrUZwbVXPzGwfbp6OdgcsctG76Ohl1xz12KO0ywV/dGEjsdU9Hcb+j3TfNNmzn3FRSP6"
    b"eF0QHQtoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGhoaGho"
    b"aGhoaGhoaGjoS6HPt4nokvMvJYd2ak4alRyPKjnTVXMQreT0XM2Rv5pziv/Nu/Vnj97GM1wpSZIkSZIkScrt"
    b"F0AGQYL+pz2dAAAAAElFTkSuQmCC"
)




@dataclass
class FileEntry:
    filename: str
    content: bytes
    mimetype: str
    upload_time: str
    client_id: str


# In-memory file storage: {file_id (UUID): FileEntry}
FILES: Dict[str, FileEntry] = {}
WORKSPACE_LOCK = Lock()

# Per-client token auth: {client_id: {tokens: [{salt, secret_hash}, ...], admin, name, registered}}
# In-memory cache of the active server's client database (state dir, not config).
# Writes always go through _clients_locked(), which auto-rebuilds ACTIVE_SERVER_CLIENTS.
# Reads are safe without a lock (dict reference swap is atomic under CPython's GIL).
ACTIVE_SERVER_CLIENTS: Dict[str, dict] = {}
_ROTATION_BLOCKED = (HTTPStatus.CONFLICT, {"error": "Token rotation in progress — call complete-client-rotation first"})
_ACTIVE_SERVER_NAME: Optional[str] = None

# Preview state: current preview for all clients
PREVIEW_STATE = {"file_id": None, "timestamp": 0}

# Pad state: shared text pad content
PAD_STATE = {"content": "", "timestamp": 0}
PAD_MAX_SIZE = 10 * 1024 * 1024  # 10MB character limit

# Per-client storage limit
MAX_STORAGE_PER_CLIENT = 4 * 1024 * 1024 * 1024  # 4GB

# Maximum request body size (applies to all POST endpoints).
# Separate from per-client storage: this caps a single request to prevent
# memory exhaustion from a malicious Content-Length header.
MAX_REQUEST_BODY = int(os.environ.get("COMPANION_MAX_REQUEST_BODY", str(MAX_STORAGE_PER_CLIENT)))

# CORS allowed origin.
# Default "*" is intentionally broad: authentication is purely token-based
# (Bearer header), not cookie/session-based, so the browser never attaches
# ambient credentials.  A malicious page cannot forge the Authorization
# header, making CSRF via CORS impossible.  Override via env var if you want
# to restrict to a specific origin anyway (e.g. "https://myhost.example").
CORS_ALLOW_ORIGIN = os.environ.get("COMPANION_CORS_ORIGIN", "*")

# Rate limiting (per-client sliding window)
RATE_LIMIT_STORE: Dict[str, List[float]] = {}
RATE_LIMIT_LOCK = Lock()
RATE_LIMIT_WINDOW = 60  # seconds
RATE_LIMIT_MAX = int(os.environ.get("COMPANION_RATE_LIMIT_MAX", "30"))
RATE_LIMIT_MAX_CLIENTS_BEFORE_CLIENT_EVICTION_CLEANUP = int(
    os.environ.get("COMPANION_RATE_LIMIT_MAX_CLIENTS_BEFORE_CLIENT_EVICTION_CLEANUP", "1000")
)

# Config file path.
# Config is declarative and read-only at runtime: the server never writes here.
# Override with COMPANION_CONFIG (lets a container bind-mount it read-only).
CONFIG_PATH = Path(
    os.environ.get("COMPANION_CONFIG", str(Path.home() / ".config" / "companion" / "config.json"))
).expanduser()
_CONFIG_LOCK_PATH = CONFIG_PATH.parent / (CONFIG_PATH.name + ".lock")

# State directory: server-owned, mutable data (the per-server client database,
# token rotation, etc.).  Kept separate from config so config can be read-only
# and a redeploy never clobbers registered clients.  Resolution order:
#   1. module global STATE_DIR (tests / explicit override)
#   2. env COMPANION_STATE_DIR
#   3. config "state-dir" key
#   4. $XDG_STATE_HOME/companion, else ~/.local/state/companion
STATE_DIR: Optional[Path] = None

# Setup logger
logger = logging.getLogger("companion")


def load_config() -> Optional[dict]:
    """Load config from CONFIG_PATH if it exists."""
    if CONFIG_PATH.exists():
        try:
            with open(CONFIG_PATH) as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            logger.warning("Failed to load config from %s: %s", CONFIG_PATH, e)
    return None


def get_state_dir() -> Path:
    """Resolve the state directory (see STATE_DIR docstring for precedence)."""
    if STATE_DIR is not None:
        return STATE_DIR
    env = os.environ.get("COMPANION_STATE_DIR")
    if env:
        return Path(env).expanduser()
    cfg = load_config()
    if cfg and cfg.get("state-dir"):
        return Path(cfg["state-dir"]).expanduser()
    xdg = os.environ.get("XDG_STATE_HOME")
    base = Path(xdg) if xdg else Path.home() / ".local" / "state"
    return base / "companion"


def _clients_path(server_name: str) -> Path:
    """Path to the client database for *server_name* (lives in the state dir)."""
    return get_state_dir() / "servers" / server_name / "clients.json"


def load_clients(server_name: str) -> dict:
    """Load the client database for *server_name*, or {} if none exists yet."""
    path = _clients_path(server_name)
    if path.exists():
        try:
            with open(path) as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            logger.warning("Failed to load clients from %s: %s", path, e)
    return {}


class ConfigError(Exception):
    """Base for all config-related errors."""


class ConfigReadError(ConfigError):
    """Raised when config cannot be read or expected entries are missing."""


class ConfigWriteError(ConfigError):
    """Raised when the config file cannot be persisted to disk."""


@contextlib.contextmanager
def _json_file_locked(path: Path):
    """Acquire an exclusive lock on <path>.lock, yield the current JSON dict
    (or {} if the file is absent), and atomic-write it back on clean exit.

    If the with-block raises, nothing is written — the on-disk file is left
    untouched. The lock + tempfile + os.replace dance makes concurrent writers
    safe and guarantees readers never see a half-written file.
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    lock_path = path.parent / (path.name + ".lock")
    lock_fd = os.open(str(lock_path), os.O_CREAT | os.O_RDWR)
    try:
        _lock_file(lock_fd)
        # Clean up stale temp files from previous failed writes
        for stale in path.parent.glob(path.stem + ".*.tmp"):
            try:
                stale.unlink()
                logger.debug("Cleaned up stale temp file: %s", stale)
            except OSError:
                logger.warning("Failed to clean up stale temp file: %s", stale)
        data = {}
        if path.exists():
            try:
                with open(path) as f:
                    data = json.load(f)
            except (json.JSONDecodeError, OSError) as e:
                logger.warning("Failed to load %s: %s", path, e)
        yield data
        # Only reached if the with-block didn't raise
        try:
            fd, tmp_path = tempfile.mkstemp(dir=str(path.parent), prefix=path.stem + ".", suffix=".tmp")
            with os.fdopen(fd, "w") as f:
                json.dump(data, f, indent=2)
            os.replace(tmp_path, str(path))
        except Exception as exc:
            raise ConfigWriteError(f"Failed to save {path}: {exc}") from exc
    finally:
        try:
            os.close(lock_fd)
        except OSError:
            logger.error(
                "Failed to close lock fd for %s — writes may deadlock until restart",
                lock_path,
            )


@contextlib.contextmanager
def _config_locked():
    """Lock and atomic-write the config file. Yields the config dict.

    Used by setup/connect CLI commands that author config. The running server
    never calls this — it only writes state (see _clients_locked).
    """
    with _json_file_locked(CONFIG_PATH) as config:
        yield config


@contextlib.contextmanager
def _clients_locked(server_name: str):
    """Lock and atomic-write the client database for *server_name*.

    Yields the clients dict (mutate it in place). On clean exit, rebuilds the
    in-memory ACTIVE_SERVER_CLIENTS cache when this is the active server. The
    reference swap is atomic under CPython's GIL, so readers never see a
    partially-built dict.
    """
    global ACTIVE_SERVER_CLIENTS
    if not server_name:
        raise ConfigReadError("No active server name — cannot persist client changes")
    with _json_file_locked(_clients_path(server_name)) as clients:
        yield clients
    # Reached only on clean exit (write succeeded). Refresh the cache.
    if _ACTIVE_SERVER_NAME == server_name:
        ACTIVE_SERVER_CLIENTS = dict(clients)


# ─────────────────────────────────────────────────────────────────────────────
# Connection security (client → server).
#
# By default this CLI is paranoid: every https:// connection requires the
# server's leaf certificate SHA-256 to be pinned in config (or via flag).
# Defense in depth — even if the CA chain validates, a different cert from the
# same CA is rejected. Bootstrap a new server with `companion fingerprint`.
# ─────────────────────────────────────────────────────────────────────────────


_INSECURE_WARNED = False  # one-shot per process; see _build_ssl_context


class CertVerificationConfigError(Exception):
    """Raised when an https connection is attempted without a pin and without --insecure."""


def make_pinned_ssl_context(pinned_sha_256, cafile=None, capath=None, cadata=None):
    """
    Returns an instance of a subclass of SSLContext that uses a subclass of SSLSocket
    that actually verifies the sha256 of the certificate during the TLS handshake
    Tested with `python-version: [3.8, 3.9, 3.10, 3.11, 3.12, 3.13]`
    Original code can be found at https://github.com/c4ffein/python-snippets
    """

    class PinnedSSLSocket(SSLSocket):
        def check_pinned_cert(self):
            der_cert_bin = self.getpeercert(True)
            if sha256(der_cert_bin).hexdigest() != pinned_sha_256:
                raise SSLCertVerificationError("Incorrect certificate checksum")

        def do_handshake(self, *args, **kwargs):
            r = super().do_handshake(*args, **kwargs)
            self.check_pinned_cert()
            return r

    class PinnedSSLContext(SSLContext):
        sslsocket_class = PinnedSSLSocket

    def create_pinned_default_context(purpose=Purpose.SERVER_AUTH):
        if not isinstance(purpose, _ASN1Object):
            raise TypeError(purpose)
        if purpose == Purpose.SERVER_AUTH:  # Verify certs and host name in client mode
            context = PinnedSSLContext(PROTOCOL_TLS_CLIENT)
            context.verify_mode, context.check_hostname = CERT_REQUIRED, True
        elif purpose == Purpose.CLIENT_AUTH:
            context = PinnedSSLContext(PROTOCOL_TLS_SERVER)
        else:
            raise ValueError(purpose)
        context.verify_flags |= _ssl.VERIFY_X509_STRICT
        if cafile or capath or cadata:
            context.load_verify_locations(cafile, capath, cadata)
        elif context.verify_mode != CERT_NONE:
            context.load_default_certs(purpose)  # Try loading default system root CA certificates, may fail silently
        if hasattr(context, "keylog_filename"):  # OpenSSL 1.1.1 keylog file
            keylogfile = os.environ.get("SSLKEYLOGFILE")
            if keylogfile and not sys_flags.ignore_environment:
                context.keylog_filename = keylogfile
        return context

    return create_pinned_default_context()


_VALID_SHA256_CHARS = frozenset("0123456789abcdef")


def _resolve_security_setting(args, server_config, key, default=None):
    """Per-key precedence: CLI flag (args.<key_attr>) > server_config[key] > default."""
    attr = key.replace("-", "_")
    cli_val = getattr(args, attr, None) if args is not None else None
    if cli_val is not None:
        return cli_val
    if server_config and key in server_config:
        return server_config[key]
    return default


def _build_ssl_context(url, args=None, server_config=None, *, allow_unpinned=False):
    """Resolve TLS settings for *url* from args/config and return an SSLContext (or None for http).

    Refuses https without a pin unless --insecure or *allow_unpinned* (used by the
    fingerprint command, which by definition has no pin yet).
    """
    global _INSECURE_WARNED

    if not url or urllib.parse.urlparse(url).scheme != "https":
        return None  # plain http needs no TLS context

    insecure = bool(_resolve_security_setting(args, server_config, "insecure", default=False))
    if insecure:
        if not _INSECURE_WARNED:
            print(
                "⚠️  --insecure: TLS verification disabled for this process. All certs will be accepted.",
                file=sys.stderr,
            )
            _INSECURE_WARNED = True
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        return ctx

    require_pin = bool(_resolve_security_setting(args, server_config, "require-pin", default=True))
    pinned_sha256 = _resolve_security_setting(args, server_config, "cert-sha256", default=None)
    ca_cert = _resolve_security_setting(args, server_config, "ca-cert", default=None)

    if pinned_sha256:
        pinned_sha256 = pinned_sha256.lower().strip()
        if len(pinned_sha256) != 64 or not all(c in _VALID_SHA256_CHARS for c in pinned_sha256):
            raise CertVerificationConfigError(f"cert-sha256 must be 64 hex characters (got {len(pinned_sha256)})")

    if require_pin and not pinned_sha256 and not allow_unpinned:
        raise CertVerificationConfigError(
            f"Refusing to connect to {url}: no cert-sha256 pinned and require-pin is on.\n"
            f"   Run `companion fingerprint --server-url {url}` to get the hash,\n"
            "   then set cert-sha256 in config (or pass --cert-sha256 <hex>),\n"
            "   or pass --insecure to bypass for this run."
        )

    if pinned_sha256:
        return make_pinned_ssl_context(pinned_sha256, cafile=ca_cert)
    # Unpinned-but-strict: standard CA verification via stdlib (used when
    # require-pin is explicitly off, or by the fingerprint cmd via allow_unpinned).
    return ssl.create_default_context(cafile=ca_cert) if ca_cert else ssl.create_default_context()


def _server_config_for(args) -> Optional[dict]:
    """Lookup the config entry for the resolved server (used by ssl-context resolution)."""
    server_name = getattr(args, "server", None)
    config = load_config()
    if not config:
        return None
    if not server_name:
        server_name = config.get("default-server")
    if not server_name:
        return None
    return config.get("servers", {}).get(server_name)


def _refuse_tls_settings_on_non_https(url, args, server_config) -> None:
    """Raise CertVerificationConfigError if *url* isn't https but any TLS knob is set.

    A TLS setting on a non-https URL would be silently ignored, and a 30x redirect
    to https would fall back to the default (system-CA) verification, defeating the
    user's stated trust intent. Better to refuse than to pretend it worked.
    """
    scheme = urllib.parse.urlparse(url).scheme if url else ""
    if scheme == "https" or not scheme:
        return
    for key in ("ca-cert", "cert-sha256", "insecure"):
        v = _resolve_security_setting(args, server_config, key, default=None)
        if v is not None and v is not False:  # value explicitly set
            raise CertVerificationConfigError(
                f"Refusing to use {url!r}: scheme is {scheme!r} but TLS setting "
                f"{key!r} is set (would be silently ignored, including on http→https redirects).\n"
                "   Either switch the URL to https://, or remove the TLS setting."
            )


def resolve_server_and_ssl(args) -> Tuple[str, Optional[str], Optional[ssl.SSLContext]]:
    """resolve_server + build TLS context for the resolved URL.

    Exits 1 on CertVerificationConfigError (e.g. https with no pin + no --insecure,
    or TLS settings on a non-https URL).
    """
    url, token = resolve_server(args)
    server_config = _server_config_for(args)
    try:
        _refuse_tls_settings_on_non_https(url, args, server_config)
        ctx = _build_ssl_context(url, args, server_config)
    except CertVerificationConfigError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)
    return url, token, ctx


def resolve_server(args) -> Tuple[str, Optional[str]]:
    """
    Resolve server URL and auth token from args and config.
    Returns (url, auth_token) where auth_token is 'client_id:client_secret' or None.

    Priority order:
    1. --server-url (explicit URL, credentials from --client-id/--client-secret or None)
    2. --server (named server from config)
    3. default-server from config
    """
    config = load_config()

    # Build auth token from CLI flags if provided
    cli_client_id = getattr(args, "client_id", None)
    cli_client_secret = getattr(args, "client_secret", None)
    cli_auth_token = f"{cli_client_id}:{cli_client_secret}" if cli_client_id and cli_client_secret else None

    def _get_auth_token(server_config):
        if cli_auth_token:
            return cli_auth_token
        cid = server_config.get("client-id")
        if not cid:
            return None
        # New format: client-secrets list (use last = newest)
        csecrets = server_config.get("client-secrets")
        if csecrets and isinstance(csecrets, list):
            return f"{cid}:{csecrets[-1]}"
        # Legacy format: single client-secret string
        csecret = server_config.get("client-secret")
        if csecret:
            return f"{cid}:{csecret}"
        return None

    # Priority 1: Explicit --server-url
    if hasattr(args, "server_url") and args.server_url:
        return args.server_url, cli_auth_token

    # Priority 2: Named --server from config
    if hasattr(args, "server") and args.server:
        if not config:
            print(f"Error: --server '{args.server}' specified but no config file found.", file=sys.stderr)
            print(f"\nCreate a config file at {CONFIG_PATH} with:", file=sys.stderr)
            _print_config_help()
            sys.exit(1)

        servers = config.get("servers", {})
        if args.server not in servers:
            available = ", ".join(servers.keys()) if servers else "(none)"
            print(f"Error: Server '{args.server}' not found in config.", file=sys.stderr)
            print(f"Available servers: {available}", file=sys.stderr)
            sys.exit(1)

        server_config = servers[args.server]
        url = server_config.get("url")
        return url, _get_auth_token(server_config)

    # Priority 3: default-server from config
    if config:
        default_name = config.get("default-server")
        if default_name:
            servers = config.get("servers", {})
            if default_name in servers:
                server_config = servers[default_name]
                url = server_config.get("url")
                return url, _get_auth_token(server_config)
            else:
                print(f"Error: default-server '{default_name}' not found in servers.", file=sys.stderr)
                sys.exit(1)

    # No server could be resolved - show helpful error
    print("Error: No server specified.", file=sys.stderr)
    print("\nTo fix this, either:", file=sys.stderr)
    print(f"  1. Create a config file at {CONFIG_PATH} with:", file=sys.stderr)
    _print_config_help()
    print("\n  2. Or specify a server explicitly:", file=sys.stderr)
    print("     companion upload --server-url http://localhost:8080 file.pdf", file=sys.stderr)
    sys.exit(1)


def _print_config_help():
    """Print example config file structure."""
    example = """{
  "default-server": "myserver",
  "servers": {
    "myserver": {
      "url": "http://localhost:8080",
      "client-id": "<hex>",
      "client-secret": "<hex>"
    }
  }
}"""
    for line in example.split("\n"):
        print(f"     {line}", file=sys.stderr)


def _maybe_bootstrap_admin(server_name: str) -> None:
    """Seed an admin from COMPANION_BOOTSTRAP_ADMIN=<client_id>:<client_secret>.

    Only acts when the env var is set and the client database has no admin yet,
    so a fresh container can come up with a way in without an interactive
    server-setup. Never overrides an existing admin.
    """
    spec = os.environ.get("COMPANION_BOOTSTRAP_ADMIN")
    if not spec:
        return
    if ":" not in spec:
        logger.warning("COMPANION_BOOTSTRAP_ADMIN must be '<client_id>:<client_secret>' — ignoring")
        return
    client_id, client_secret = spec.split(":", 1)
    if not client_id or not client_secret:
        logger.warning("COMPANION_BOOTSTRAP_ADMIN missing id or secret — ignoring")
        return
    if any(c.get("admin") for c in load_clients(server_name).values()):
        return  # already have an admin; never override
    salt = secrets.token_hex(16)
    secret_hash = hashlib.sha256((salt + client_secret).encode()).hexdigest()
    try:
        with _clients_locked(server_name) as clients:
            if client_id in clients:
                return
            clients[client_id] = {
                "tokens": [{"salt": salt, "secret_hash": secret_hash}],
                "admin": True,
                "name": "bootstrap",
                "registered": datetime.now().isoformat(),
            }
    except ConfigError as exc:
        logger.error("Failed to seed bootstrap admin: %s", exc)
        return
    logger.info("Seeded bootstrap admin '%s' for server '%s'", client_id, server_name)


def resolve_server_config(args) -> int:
    """Resolve the listen port for server mode and load the client database.

    Sets _ACTIVE_SERVER_NAME and ACTIVE_SERVER_CLIENTS. Config is optional:
    with no config file the server runs under the "default" server name and
    reads its clients from the state dir (seedable via COMPANION_BOOTSTRAP_ADMIN).

    Port precedence:        --port > port in server's config URL > COMPANION_PORT > 8080
    Server-name precedence: --server > COMPANION_DEFAULT_SERVER > config default-server > "default"
    """
    global _ACTIVE_SERVER_NAME, ACTIVE_SERVER_CLIENTS
    config = load_config()
    port = getattr(args, "port", None)
    servers = config.get("servers", {}) if config else {}

    server_name = getattr(args, "server", None) or os.environ.get("COMPANION_DEFAULT_SERVER")
    server_config = None
    if server_name:
        # Only enforce membership when a config with a servers map exists.
        if servers and server_name not in servers:
            available = ", ".join(servers.keys()) if servers else "(none)"
            print(f"Error: Server '{server_name}' not found in config.", file=sys.stderr)
            print(f"Available servers: {available}", file=sys.stderr)
            sys.exit(1)
        server_config = servers.get(server_name)
    elif config and config.get("default-server"):
        server_name = config["default-server"]
        server_config = servers.get(server_name)

    if not server_name:
        server_name = "default"
    _ACTIVE_SERVER_NAME = server_name

    # Port resolution
    if port is None and server_config:
        parsed = urllib.parse.urlparse(server_config.get("url", ""))
        if parsed.port:
            port = parsed.port
    if port is None and os.environ.get("COMPANION_PORT"):
        try:
            port = int(os.environ["COMPANION_PORT"])
        except ValueError:
            print(f"Error: invalid COMPANION_PORT: {os.environ['COMPANION_PORT']!r}", file=sys.stderr)
            sys.exit(1)
    if port is None:
        port = 8080

    # Seed a bootstrap admin if requested, then load the client database.
    _maybe_bootstrap_admin(server_name)
    ACTIVE_SERVER_CLIENTS = load_clients(server_name)

    if not ACTIVE_SERVER_CLIENTS:
        print("Error: No clients configured.", file=sys.stderr)
        print("Run 'companion server-setup' to configure the server first,", file=sys.stderr)
        print("or set COMPANION_BOOTSTRAP_ADMIN=<client_id>:<client_secret>.", file=sys.stderr)
        sys.exit(1)

    return port


class Auth(enum.Enum):
    NONE = "none"
    REGULAR = "regular"
    ADMIN = "admin"


_ROUTES = []  # [(http_method, path_regex, param_names, handler)]


def _route(method, path, auth=Auth.REGULAR, rate_limit=False, parse_body=False, max_body=None, rotation_ok=False):
    """Decorator for route handlers. Registers the route and handles auth, rate limiting, body reading.

    Path patterns use {name} for parameters, e.g. "/download/{file_id}".
    The decorated function receives keyword arguments: client, body, and any path params.

    rotation_ok: if False (default) and the client has a rotation in progress (2 tokens),
    the request is rejected with 409. Set to True for rotation endpoints.
    """

    # Compile path pattern to regex: "/download/{file_id}" -> r"^/download/(?P<file_id>[A-Za-z0-9-]+)$"
    param_names = re.findall(r"\{(\w+)\}", path)
    pattern = "^" + re.sub(r"\{(\w+)\}", r"(?P<\1>[A-Za-z0-9-]+)", path) + "$"
    path_regex = re.compile(pattern)

    def decorator(fn):
        if rate_limit and auth == Auth.NONE:
            raise ValueError(f"rate_limit requires authentication, but auth=Auth.NONE on {fn.__name__}")

        @functools.wraps(fn)
        def wrapper(self, **kwargs):
            # Authenticate
            client = None
            if auth != Auth.NONE:
                client = self._authenticate()
                if not client:
                    return self._AUTH_FAILED
                if auth == Auth.ADMIN and not client.get("admin"):
                    return self._ADMIN_REQUIRED

                # Block if rotation in progress (2 tokens) unless this is a rotation endpoint
                if not rotation_ok:
                    tokens = client.get("tokens")
                    if tokens is not None and len(tokens) > 1:
                        return _ROTATION_BLOCKED

            # Rate limit
            if rate_limit:
                if not self._check_rate_limit(client["client_id"]):
                    return self._RATE_LIMITED

            # Read body
            request_body = None
            if parse_body:
                request_body = self._read_body(max_bytes=max_body or MAX_REQUEST_BODY)
                if request_body is None:
                    return None

            return fn(self, client=client, body=request_body, **kwargs)

        _ROUTES.append((method, path_regex, param_names, wrapper))
        return wrapper

    return decorator


class FileShareHandler(http.server.BaseHTTPRequestHandler):
    """HTTP handler for file sharing server"""

    def _set_headers(self, status=HTTPStatus.OK, content_type="text/html"):
        self.send_response(status)
        self.send_header("Content-type", content_type)
        self.send_header("Access-Control-Allow-Origin", CORS_ALLOW_ORIGIN)
        self.end_headers()

    def _send_result(self, result):
        """Send a handler's result as the HTTP response. None means already handled."""
        if result is None:
            return
        status, data = result
        if isinstance(data, FileEntry):
            self._send_file(data)
        elif isinstance(data, str):
            self._set_headers(status)
            self.wfile.write(data.encode())
        else:
            self._send_json(status, data)

    def _send_json(self, status, data):
        """Send a JSON response."""
        self._set_headers(status, "application/json")
        self.wfile.write(json.dumps(data).encode())

    def _send_file(self, entry):
        """Send a file response with appropriate headers."""
        safe_name = sanitize_filename(entry.filename)
        utf8_name = urllib.parse.quote(entry.filename)
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", entry.mimetype)
        self.send_header("Content-Disposition", f"inline; filename=\"{safe_name}\"; filename*=UTF-8''{utf8_name}")
        self.send_header("Content-Length", str(len(entry.content)))
        self.send_header("Access-Control-Allow-Origin", CORS_ALLOW_ORIGIN)
        self.end_headers()
        self.wfile.write(entry.content)

    # Allowed charset for client_id: alphanumeric + hyphens (matches registration validation).
    _VALID_ID_CHARS = frozenset("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-")
    # Allowed charset for client_secret: hex digits (generated by secrets.token_hex).
    _VALID_SECRET_CHARS = frozenset("0123456789abcdef")
    _VALID_NAME_CHARS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-")

    def _authenticate(self) -> Optional[dict]:
        """Parse Bearer client_id:client_secret, verify against token list, return client info or None.

        Supports both legacy format (flat salt/secret_hash) and new format (tokens list).
        The returned dict includes '_client_secret' for re-verification under lock.
        """
        auth_header = self.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return None
        token = auth_header[7:]
        if ":" not in token:
            return None
        client_id, client_secret = token.split(":", 1)
        # Validate charset: reject obviously malformed tokens early.
        if not client_id or not all(c in self._VALID_ID_CHARS for c in client_id):
            return None
        if not client_secret or not all(c in self._VALID_SECRET_CHARS for c in client_secret):
            return None
        client = ACTIVE_SERVER_CLIENTS.get(client_id)
        if not client:
            return None
        tokens = client.get("tokens")
        if tokens is None:
            # Legacy format: flat salt/secret_hash
            tokens = [{"salt": client["salt"], "secret_hash": client["secret_hash"]}]
        for i, tok in enumerate(tokens):
            expected = hashlib.sha256((tok["salt"] + client_secret).encode()).hexdigest()
            if hmac.compare_digest(tok["secret_hash"], expected):
                return {"client_id": client_id, "_client_secret": client_secret, **client}
        return None

    _AUTH_FAILED = (HTTPStatus.UNAUTHORIZED, {"error": "Invalid credentials"})
    _ADMIN_REQUIRED = (HTTPStatus.FORBIDDEN, {"error": "Admin access required"})
    _RATE_LIMITED = (HTTPStatus.TOO_MANY_REQUESTS, {"error": "Rate limit exceeded"})

    def _check_rate_limit(self, client_id: str) -> bool:
        """Per-client sliding window rate limit. Returns True if allowed, False if not."""
        now = time.monotonic()
        with RATE_LIMIT_LOCK:
            # Cleanup when store gets large
            if len(RATE_LIMIT_STORE) > RATE_LIMIT_MAX_CLIENTS_BEFORE_CLIENT_EVICTION_CLEANUP:
                cutoff = now - RATE_LIMIT_WINDOW
                to_delete = [k for k, v in RATE_LIMIT_STORE.items() if not v or v[-1] < cutoff]
                for k in to_delete:
                    del RATE_LIMIT_STORE[k]
            timestamps = RATE_LIMIT_STORE.setdefault(client_id, [])
            # Remove expired entries
            cutoff = now - RATE_LIMIT_WINDOW
            timestamps[:] = [t for t in timestamps if t > cutoff]
            if len(timestamps) >= RATE_LIMIT_MAX:
                return False
            timestamps.append(now)
        return True

    def _read_body(self, max_bytes: int = MAX_REQUEST_BODY) -> Optional[bytes]:
        """Read request body up to *max_bytes*.  Sends 411/413/400 on error and returns None."""
        raw = self.headers.get("Content-Length")
        if raw is None:
            self._send_json(HTTPStatus.LENGTH_REQUIRED, {"error": "Content-Length header is required"})
            return None
        try:
            length = int(raw)
        except (ValueError, TypeError):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "Invalid Content-Length"})
            return None
        if length < 0 or length > max_bytes:
            self._send_json(
                HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {"error": f"Request body too large (max {max_bytes} bytes)"}
            )
            return None
        return self.rfile.read(length)

    _VALID_PATH_PARAM_CHARS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-")

    def _dispatch(self):
        """Match request to a registered @_route handler and send the result."""
        request_method = self.command
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path
        for http_method, path_regex, param_names, handler in _ROUTES:
            if http_method != request_method:
                continue
            m = path_regex.match(path)
            if m:
                params = {name: urllib.parse.unquote(m.group(name)) for name in param_names}
                # dual validation of decoded params against allowed charset - should actually never be triggered
                if any(not all(c in self._VALID_PATH_PARAM_CHARS for c in v) for v in params.values()):
                    self._send_result((HTTPStatus.BAD_REQUEST, {"error": "Invalid path parameter"}))
                    return
                self._send_result(handler(self, **params))
                return
        self._send_result((HTTPStatus.NOT_FOUND, {"error": "Not found"}))

    do_GET = _dispatch
    do_POST = _dispatch
    do_DELETE = _dispatch

    @_route("POST", "/api/upload", auth=Auth.REGULAR, rate_limit=True, parse_body=True)
    def _handle_multipart_upload(self, client=None, body=None):
        """Parse multipart form data and store file.

        Simplified multipart parser — intentionally not a full RFC 2046 implementation.
        This is sufficient because the only real clients are:
        - The web UI (browser FormData — always well-formed)
        - The CLI upload_file() function (generates correct multipart)
        - curl / standard HTTP tools (also well-formed)

        Known simplifications:
        - Boundary is extracted by splitting Content-Type on ";", then on
          "boundary=". Quoted boundaries (required by RFC 2045 when the
          value contains tspecials like : , / ( ) = ?) are handled by
          stripping quotes. ";" is in tspecials but not in RFC 2046's
          bchars, so a valid boundary never contains ";" and the split
          is safe. In practice browsers/curl only generate alphanumeric +
          dash boundaries that don't need quoting at all.
        - body.split(boundary) assumes the boundary doesn't appear in file
          content. This is always true in practice: the sender picks a boundary
          specifically to avoid collisions.
        - Filename is extracted by splitting on "filename=", not by parsing
          Content-Disposition per RFC 6266. Works for all browser/curl output.

        Security:
        - a malformed payload can only corrupt the attacker's own upload
        - we sanitize anything that actually matters in the content of the request
        """
        # Parse multipart form data manually (simple version)
        content_type = self.headers.get("Content-Type", "")
        if "multipart/form-data" not in content_type:
            return HTTPStatus.BAD_REQUEST, {"error": "Expected multipart/form-data"}

        client_id = client["client_id"]

        # Extract boundary
        boundary = None
        for part in content_type.split(";"):
            if "boundary=" in part:
                raw = part.split("boundary=")[1].strip()
                if '"' in raw:
                    if not raw.startswith('"') or not raw.endswith('"') or len(raw) < 2 or '"' in raw[1:-1]:
                        return HTTPStatus.BAD_REQUEST, {"error": "Malformed boundary in Content-Type"}
                    boundary = raw[1:-1]
                else:
                    boundary = raw
                break

        if not boundary:
            return HTTPStatus.BAD_REQUEST, {"error": "No boundary found"}

        # Split by boundary
        parts = body.split(f"--{boundary}".encode())

        for part in parts:
            if b"Content-Disposition" in part and b"filename=" in part:
                # Extract filename
                headers_end = part.find(b"\r\n\r\n")
                if headers_end == -1:
                    continue

                headers = part[:headers_end].decode("utf-8", errors="ignore")
                content = part[headers_end + 4 :]

                # Remove trailing \r\n
                if content.endswith(b"\r\n"):
                    content = content[:-2]

                # Parse filename
                filename = None
                for line in headers.split("\n"):
                    if "filename=" in line:
                        filename_part = line.split("filename=")[1]
                        filename = filename_part.strip().strip('"').strip("'")
                        break

                if filename:
                    # Guess mimetype
                    mimetype, _ = mimetypes.guess_type(filename)
                    if not mimetype:
                        mimetype = "application/octet-stream"

                    upload_time = datetime.now().isoformat()
                    file_id = str(uuid.uuid4())

                    # Check per-client storage limit and insert atomically
                    with WORKSPACE_LOCK:
                        current_usage = sum(len(f.content) for f in FILES.values() if f.client_id == client_id)
                        if current_usage + len(content) > MAX_STORAGE_PER_CLIENT:
                            return HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {
                                "error": "Storage limit exceeded for this client"
                            }
                        FILES[file_id] = FileEntry(filename, content, mimetype, upload_time, client_id)

                    return HTTPStatus.OK, {
                        "success": True,
                        "id": file_id,
                        "filename": filename,
                        "normalized_name": sanitize_filename(filename),
                        "size": len(content),
                    }

        return HTTPStatus.BAD_REQUEST, {"error": "No file found in upload"}

