    @_route("POST", "/api/pad", auth=Auth.REGULAR, rate_limit=True, parse_body=True, max_body=PAD_MAX_SIZE + 1024)
    def _handle_pad_update(self, client=None, body=None):
        """Handle updating the pad content"""
        try:
            data = json.loads(body.decode())
            content = data.get("content", "")

            # Check size limit
            if len(content) > PAD_MAX_SIZE:
                return HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {
                    "error": f"Content exceeds maximum size of {PAD_MAX_SIZE} bytes"
                }

            # Update pad state atomically
            with WORKSPACE_LOCK:
                PAD_STATE["content"] = content
                PAD_STATE["timestamp"] = _next_timestamp(PAD_STATE["timestamp"])
                timestamp = PAD_STATE["timestamp"]

            return HTTPStatus.OK, {"success": True, "timestamp": timestamp, "size": len(content)}

        except (json.JSONDecodeError, KeyError):
            return HTTPStatus.BAD_REQUEST, {"error": "Invalid JSON"}

    @_route("POST", "/api/clients/register", auth=Auth.ADMIN, rate_limit=True, parse_body=True, max_body=4096)
    def _handle_register_client(self, client=None, body=None):
        """Handle client registration. Always requires admin auth."""
        try:
            data = json.loads(body.decode())
            client_id = data.get("client_id")
            client_secret = data.get("client_secret")
            name = data.get("name", "")

            if not client_id or not client_secret:
                return HTTPStatus.BAD_REQUEST, {"error": "client_id and client_secret are required"}

            # Validate client_id: 1-64 chars, alphanumeric + hyphens only
            if len(client_id) > 64 or not client_id or not all(c in self._VALID_ID_CHARS for c in client_id):
                return HTTPStatus.BAD_REQUEST, {
                    "error": "client_id must be 1-64 characters, alphanumeric and hyphens only"
                }

            # Validate name: 0-128 chars, letters/digits/underscores/dots/hyphens only
            if len(name) > 128 or not all(c in self._VALID_NAME_CHARS for c in name):
                return HTTPStatus.BAD_REQUEST, {
                    "error": "name must be 0-128 characters (letters, digits, underscores, dots, hyphens)"
                }

            salt = secrets.token_hex(16)
            secret_hash = hashlib.sha256((salt + client_secret).encode()).hexdigest()

            try:
                with _clients_locked(_ACTIVE_SERVER_NAME) as clients:
                    if client_id in clients:
                        return HTTPStatus.CONFLICT, {"error": "client_id already exists"}
                    clients[client_id] = {
                        "tokens": [{"salt": salt, "secret_hash": secret_hash}],
                        "admin": False,
                        "name": name,
                        "registered": datetime.now().isoformat(),
                    }
            except ConfigError as exc:
                logger.error("Failed to register client: %s", exc)
                return HTTPStatus.INTERNAL_SERVER_ERROR, {"error": "Failed to persist client"}

            return HTTPStatus.OK, {"success": True, "client_id": client_id, "admin": False, "name": name}

        except (json.JSONDecodeError, KeyError):
            return HTTPStatus.BAD_REQUEST, {"error": "Invalid JSON"}

    @_route("POST", "/api/token/start-client-rotation", auth=Auth.REGULAR, rate_limit=True, rotation_ok=True)
    def _handle_start_client_rotation(self, client=None, body=None):
        """Start token rotation: generate a new token and append it to the client's token list.

        Fails if already in rotation (2 tokens) — the client must complete first.
        Returns the new secret so the client can save it.
        """
        client_id = client["client_id"]
        new_secret = secrets.token_hex(32)
        salt = secrets.token_hex(16)
        secret_hash = hashlib.sha256((salt + new_secret).encode()).hexdigest()
        new_token_entry = {"salt": salt, "secret_hash": secret_hash}

        try:
            with _clients_locked(_ACTIVE_SERVER_NAME) as clients:
                if client_id not in clients:
                    return HTTPStatus.NOT_FOUND, {"error": "Client not found"}
                entry = clients[client_id]
                tokens = entry.get("tokens")
                if tokens is None:
                    # Migrate legacy format
                    tokens = [{"salt": entry.pop("salt"), "secret_hash": entry.pop("secret_hash")}]
                if len(tokens) >= 2:
                    return _ROTATION_BLOCKED
                tokens.append(new_token_entry)
                entry["tokens"] = tokens
        except ConfigError as exc:
            logger.error("Failed to start rotation for %s: %s", client_id, exc)
            return HTTPStatus.INTERNAL_SERVER_ERROR, {"error": "Failed to persist rotation"}

        return HTTPStatus.OK, {"success": True, "client_id": client_id, "new_secret": new_secret}

    @_route("POST", "/api/token/complete-client-rotation", auth=Auth.REGULAR, rotation_ok=True)
    def _handle_complete_client_rotation(self, client=None, body=None):
        """Complete token rotation: keep only the token that authenticated this request.

        The token used in the Authorization header is the one that survives.
        Idempotent: if already down to 1 token, this is a no-op success.
        """
        client_id = client["client_id"]
        client_secret = client["_client_secret"]

        try:
            with _clients_locked(_ACTIVE_SERVER_NAME) as clients:
                if client_id not in clients:
                    return HTTPStatus.NOT_FOUND, {"error": "Client not found"}
                entry = clients[client_id]
                tokens = entry.get("tokens")
                if tokens is None:
                    # Migrate legacy format to tokens list
                    entry["tokens"] = [{"salt": entry.pop("salt"), "secret_hash": entry.pop("secret_hash")}]
                    return HTTPStatus.OK, {"success": True, "client_id": client_id}
                if len(tokens) == 1:
                    return HTTPStatus.OK, {"success": True, "client_id": client_id}
                # Re-verify which token matches under the lock (index may be stale)
                for i, tok in enumerate(tokens):
                    expected = hashlib.sha256((tok["salt"] + client_secret).encode()).hexdigest()
                    if hmac.compare_digest(tok["secret_hash"], expected):
                        entry["tokens"] = [tok]
                        break
                else:
                    return self._AUTH_FAILED
        except ConfigError as exc:
            logger.error("Failed to complete rotation for %s: %s", client_id, exc)
            return HTTPStatus.INTERNAL_SERVER_ERROR, {"error": "Failed to persist rotation"}

        return HTTPStatus.OK, {"success": True, "client_id": client_id}

    def do_OPTIONS(self):
        """Handle CORS preflight requests"""
        self.send_response(HTTPStatus.NO_CONTENT)
        self.send_header("Access-Control-Allow-Origin", CORS_ALLOW_ORIGIN)
        self.send_header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Authorization, Content-Type")
        self.end_headers()

    @_route("DELETE", "/api/clients/{target_client_id}", auth=Auth.ADMIN)
    def _handle_delete_client(self, target_client_id: str, client=None, body=None):
        """Handle deleting a registered client (admin only, no self-deletion)."""

        if client["client_id"] == target_client_id:
            return HTTPStatus.BAD_REQUEST, {"error": "Cannot delete yourself"}

        try:
            with _clients_locked(_ACTIVE_SERVER_NAME) as clients:
                if target_client_id not in clients:
                    return HTTPStatus.NOT_FOUND, {"error": "Client not found"}
                del clients[target_client_id]
        except ConfigError as exc:
            logger.error("Failed to delete client: %s", exc)
            return HTTPStatus.INTERNAL_SERVER_ERROR, {"error": "Failed to persist client deletion"}

        return HTTPStatus.OK, {"success": True, "deleted": target_client_id}

    @_route("GET", "/api/clients", auth=Auth.ADMIN)
    def _handle_list_clients(self, client=None, body=None):
        """Handle listing registered clients (admin only, secrets excluded)"""
        clients_list = [
            {
                "client_id": cid,
                "admin": info["admin"],
                "name": info.get("name", ""),
                "registered": info.get("registered", ""),
            }
            for cid, info in ACTIVE_SERVER_CLIENTS.items()
        ]

        return HTTPStatus.OK, clients_list

