def _rotation_request(server_url: str, endpoint: str, auth_token: str, ssl_context=None):
    """POST to a rotation endpoint. Returns parsed JSON response."""
    url = f"{server_url.rstrip('/')}{endpoint}"
    headers = {"Authorization": f"Bearer {auth_token}", "Content-Length": "0"}
    req = urllib.request.Request(url, data=b"", headers=headers, method="POST")
    with urllib.request.urlopen(req, context=ssl_context) as response:
        return json.loads(response.read().decode())


def start_client_rotation(server_url: str, auth_token: str, ssl_context=None):
    """Call start-client-rotation endpoint. Returns new_secret or None."""
    result = _rotation_request(server_url, "/api/token/start-client-rotation", auth_token, ssl_context=ssl_context)
    return result.get("new_secret")


def complete_client_rotation(server_url: str, auth_token: str, ssl_context=None):
    """Call complete-client-rotation endpoint. Returns True on success."""
    result = _rotation_request(server_url, "/api/token/complete-client-rotation", auth_token, ssl_context=ssl_context)
    return result.get("success", False)


def _resolve_server_name(args):
    """Resolve server name from args or config default."""
    server_name = getattr(args, "server", None)
    if not server_name:
        config = load_config()
        if config:
            server_name = config.get("default-server")
    return server_name


def _get_all_local_secrets(server_name):
    """Read all client secrets from local config for a server, oldest first."""
    config = load_config()
    if not config or not server_name:
        return []
    servers = config.get("servers", {})
    if server_name not in servers:
        return []
    entry = servers[server_name]
    csecrets = entry.get("client-secrets")
    if csecrets and isinstance(csecrets, list):
        return list(csecrets)
    csecret = entry.get("client-secret")
    if csecret:
        return [csecret]
    return []


def _save_secrets(server_name, secrets_list):
    """Write client-secrets list to local config for a server. Raises ConfigWriteError if server not found."""
    with _config_locked() as config:
        servers = config.get("servers", {})
        if not server_name or server_name not in servers:
            raise ConfigWriteError(f"Server '{server_name}' not found in config")
        entry = servers[server_name]
        entry["client-secrets"] = secrets_list
        entry.pop("client-secret", None)


def rotate_cmd(args):
    """Full token rotation: start rotation, save new secret, complete rotation.

    Requires exactly 1 local secret. If local config has 2 secrets (interrupted
    previous rotation), use complete-rotation instead.

    Handles the case where the server already has 2 tokens (409 on start) by
    completing the stale rotation with our single secret first.
    """
    server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
    if not auth_token:
        print("Error: Credentials required to rotate.", file=sys.stderr)
        sys.exit(1)

    server_name = _resolve_server_name(args)
    config = load_config()
    client_id = config["servers"][server_name].get("client-id") if config else None
    if not client_id:
        print("Error: No client-id found in config.", file=sys.stderr)
        sys.exit(1)
    all_secrets = _get_all_local_secrets(server_name)

    if len(all_secrets) > 1:
        print("Error: Local config has multiple secrets — a previous rotation was interrupted.", file=sys.stderr)
        print("   Run 'companion complete-rotation' to resolve it first.", file=sys.stderr)
        sys.exit(1)

    try:
        # Step 1: Start rotation — server generates new token
        print("🔄 Starting token rotation...")
        try:
            new_secret = start_client_rotation(server_url, auth_token, ssl_context=ssl_ctx)
        except urllib.error.HTTPError as e:
            if e.code == 409:
                # Server already has 2 tokens — stale rotation from a previous run.
                # Complete it with our single secret, then ask user to rotate again.
                complete_client_rotation(server_url, auth_token, ssl_context=ssl_ctx)
                print("⚠️  Previous rotation was incomplete. Resolved it, but did not rotate.")
                print("   Please run 'companion rotate' again.")
                sys.exit(1)
            raise

        if not new_secret:
            print("❌ Failed to start rotation: no new secret returned", file=sys.stderr)
            sys.exit(1)

        # Step 2: Save both secrets locally (old + new)
        old_secret = auth_token.split(":", 1)[1]
        try:
            _save_secrets(server_name, [old_secret, new_secret])
        except ConfigWriteError as exc:
            print(f"❌ Failed to save new secret locally: {exc}", file=sys.stderr)
            logger.debug("New secret: %s", new_secret)
            print("   Save it manually and run 'companion complete-rotation' to finish.", file=sys.stderr)
            sys.exit(1)

        # Step 3: Complete rotation — tell server to drop old token
        new_auth_token = f"{client_id}:{new_secret}"
        print("🔄 Completing rotation...")
        complete_client_rotation(server_url, new_auth_token, ssl_context=ssl_ctx)

        # Step 4: Update local config to keep only the new secret
        try:
            _save_secrets(server_name, [new_secret])
        except ConfigWriteError as exc:
            print(f"⚠️  Rotation completed on server but local cleanup failed: {exc}", file=sys.stderr)
            print("   Run 'companion complete-rotation' to clean up.", file=sys.stderr)
            sys.exit(1)

        print("✅ Token rotation complete!")
        logger.debug("New secret: %s", new_secret)
        print("   The old secret has been revoked.")

    except urllib.error.HTTPError as e:
        error_body = e.read().decode()
        try:
            error_json = json.loads(error_body)
            print(f"❌ Rotation failed: {error_json.get('error', 'Unknown error')}")
        except (json.JSONDecodeError, KeyError):
            print(f"❌ Rotation failed: HTTP {e.code}")
        sys.exit(1)
    except Exception as e:
        print(f"❌ Rotation failed: {e}")
        sys.exit(1)


def complete_rotation_cmd(args):
    """Complete an interrupted rotation: try each local secret, converge to 1.

    Requires exactly 2 local secrets. Tries each against the server (last first,
    since it's the newest). The first secret that authenticates wins — completes
    server-side rotation with it and saves only that secret locally.
    """
    server_url, _, ssl_ctx = resolve_server_and_ssl(args)
    if not server_url:
        print("Error: Server URL required.", file=sys.stderr)
        sys.exit(1)

    server_name = _resolve_server_name(args)
    all_secrets = _get_all_local_secrets(server_name)
    config = load_config()
    client_id = config["servers"][server_name].get("client-id") if config else None

    if not client_id:
        print("Error: No client-id found in config.", file=sys.stderr)
        sys.exit(1)

    if len(all_secrets) < 2:
        print("Error: Local config has only 1 secret — nothing to complete.", file=sys.stderr)
        print("   Run 'companion rotate' to start a new rotation.", file=sys.stderr)
        sys.exit(1)

    print("🔄 Completing interrupted rotation...")

    # Try each secret, newest (last) first
    for s in reversed(all_secrets):
        token = f"{client_id}:{s}"
        try:
            complete_client_rotation(server_url, token, ssl_context=ssl_ctx)
            _save_secrets(server_name, [s])
            print("✅ Rotation completed!")
            logger.debug("Surviving secret: %s", s)
            return
        except urllib.error.HTTPError as e:
            if e.code == 401:
                continue  # This secret doesn't match any server token
            error_body = e.read().decode()
            try:
                error_json = json.loads(error_body)
                print(f"❌ Completion failed: {error_json.get('error', 'Unknown error')}")
            except (json.JSONDecodeError, KeyError):
                print(f"❌ Completion failed: HTTP {e.code}")
            sys.exit(1)
        except Exception as e:
            print(f"❌ Completion failed: {e}")
            sys.exit(1)

    print("❌ No local secret matches any server token.", file=sys.stderr)
    print("   You may need new credentials from your admin.", file=sys.stderr)
    sys.exit(1)


def server_setup_cmd(args):
    """First-time server setup. Writes admin client to config.

    Default (non-interactive): errors if --url is missing; auto-generates
    client-id/secret; defaults server name to "default".

    With --interactive: prompts for each un-provided field in order.
    """
    interactive = getattr(args, "interactive", False)
    config = load_config() or {}
    servers = config.get("servers", {})

    # Show existing servers
    if servers:
        print("Existing servers:")
        for name, srv in servers.items():
            print(f"  {name}: {srv.get('url', '(no url)')}")
        print()

    # Resolve server name
    server_name = getattr(args, "server", None)
    if not server_name:
        if interactive:
            server_name = input("Server name [default]: ").strip() or "default"
        else:
            server_name = "default"

    # Resolve URL
    url = getattr(args, "url", None)
    if not url:
        if interactive:
            hint = ""
            if server_name in servers and servers[server_name].get("url"):
                hint = servers[server_name]["url"]
            url = input(f"Server URL [{hint or 'http://localhost:8080'}]: ").strip()
            if not url:
                url = hint or "http://localhost:8080"
        else:
            # Non-interactive: --url is required
            print("Error: missing required flag: --url", file=sys.stderr)
            print("  Tip: use --interactive to be prompted for missing fields.", file=sys.stderr)
            sys.exit(1)

    # Resolve client ID
    client_id = getattr(args, "client_id", None)
    if not client_id:
        if interactive:
            client_id = input("Admin client ID (blank to auto-generate) [auto-generate]: ").strip()
        if not client_id:
            client_id = secrets.token_hex(16)
            print(f"  Generated client ID: {client_id}")

    # Resolve client secret
    client_secret = getattr(args, "client_secret", None)
    if not client_secret:
        if interactive:
            client_secret = input("Admin client secret (blank to auto-generate) [auto-generate]: ").strip()
        if not client_secret:
            client_secret = secrets.token_hex(32)
            print(f"  Generated client secret: {client_secret}")

    # Resolve client name
    client_name = getattr(args, "client_name", "") or ""
    if not client_name and interactive:
        client_name = input("Admin client name (blank for none): ").strip()

    # Compute salted hash
    salt = secrets.token_hex(16)
    secret_hash = hashlib.sha256((salt + client_secret).encode()).hexdigest()

    try:
        # Config (declarative): server URL + the CLI's own connect credentials.
        with _config_locked() as cfg:
            srvs = cfg.setdefault("servers", {})
            entry = srvs.setdefault(server_name, {})
            entry["url"] = url
            if "default-server" not in cfg:
                cfg["default-server"] = server_name
            entry["client-id"] = client_id
            entry["client-secrets"] = [client_secret]
        # State (server-owned): the admin client lands in the client database.
        with _clients_locked(server_name) as clients:
            clients[client_id] = {
                "tokens": [{"salt": salt, "secret_hash": secret_hash}],
                "admin": True,
                "name": client_name,
                "registered": datetime.now().isoformat(),
            }
    except ConfigWriteError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"\n✅ Server '{server_name}' configured at {url}")
    print(f"   Admin client ID:     {client_id}")
    print(f"   Admin client secret: {client_secret}")
    print(f"   Config saved to {CONFIG_PATH}")
    print("\n   Save these credentials — the secret cannot be retrieved later.")


def server_add_user_cmd(args):
    """Add a user client to a configured server's config.

    Default (non-interactive): auto-generates client-id/secret, uses config
    defaults.  With --interactive: prompts for each un-provided field.
    """
    interactive = getattr(args, "interactive", False)
    server_name = getattr(args, "server", None)
    is_admin = getattr(args, "admin", False)

    # Resolve client ID
    client_id = getattr(args, "client_id", None)
    if not client_id:
        if interactive:
            client_id = input("Client ID (blank to auto-generate) [auto-generate]: ").strip()
        if not client_id:
            client_id = secrets.token_hex(16)
            print(f"  Generated client ID: {client_id}")

    # Resolve client secret
    client_secret = getattr(args, "client_secret", None)
    if not client_secret:
        if interactive:
            client_secret = input("Client secret (blank to auto-generate) [auto-generate]: ").strip()
        if not client_secret:
            client_secret = secrets.token_hex(32)
            print(f"  Generated client secret: {client_secret}")

    # Resolve client name
    client_name = getattr(args, "client_name", "") or ""
    if not client_name and interactive:
        client_name = input("Client name (blank for none): ").strip()

    # Compute salted hash
    salt = secrets.token_hex(16)
    secret_hash = hashlib.sha256((salt + client_secret).encode()).hexdigest()

    config = load_config()
    if not config:
        print("Error: No config file found.", file=sys.stderr)
        print("Run 'companion server-setup' first.", file=sys.stderr)
        sys.exit(1)
    if not server_name:
        server_name = config.get("default-server")
    if not server_name:
        print("Error: No server specified and no default-server in config.", file=sys.stderr)
        sys.exit(1)
    servers = config.get("servers", {})
    if server_name not in servers:
        available = ", ".join(servers.keys()) if servers else "(none)"
        print(f"Error: Server '{server_name}' not found. Available: {available}", file=sys.stderr)
        sys.exit(1)

    try:
        with _clients_locked(server_name) as clients:
            if client_id in clients:
                print(f"Error: Client '{client_id}' already exists on server '{server_name}'.", file=sys.stderr)
                sys.exit(1)
            clients[client_id] = {
                "tokens": [{"salt": salt, "secret_hash": secret_hash}],
                "admin": is_admin,
                "name": client_name,
                "registered": datetime.now().isoformat(),
            }
    except ConfigWriteError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    role = "admin" if is_admin else "user"
    print(f"\n✅ Added {role} client to server '{server_name}'")
    print(f"   Client ID:     {client_id}")
    print(f"   Client secret: {client_secret}")
    print(f"   Config saved to {CONFIG_PATH}")
    print("\n   Save these credentials — the secret cannot be retrieved later.")


def connect_cmd(args):
    """Save server connection credentials locally (no server contact).

    Default (non-interactive): all of --url, --client-id, --client-secret are
    required.  With --interactive: prompts for each un-provided field.
    """
    interactive = getattr(args, "interactive", False)
    server_name = getattr(args, "server", None) or "default"

    url = getattr(args, "url", None)
    client_id = getattr(args, "client_id", None)
    client_secret = getattr(args, "client_secret", None)

    if interactive:
        if not url:
            url = input("Server URL: ").strip()
        if not client_id:
            client_id = input("Client ID: ").strip()
        if not client_secret:
            client_secret = input("Client secret: ").strip()

    # Validate required fields
    missing = []
    if not url:
        missing.append("--url")
    if not client_id:
        missing.append("--client-id")
    if not client_secret:
        missing.append("--client-secret")
    if missing:
        print(f"Error: Missing required flags: {', '.join(missing)}", file=sys.stderr)
        print("Provide all flags or use --interactive to be prompted.", file=sys.stderr)
        sys.exit(1)

    try:
        with _config_locked() as config:
            servers = config.setdefault("servers", {})
            if server_name in servers:
                print(f"Error: Server '{server_name}' already exists. Use a different name.", file=sys.stderr)
                sys.exit(1)
            servers[server_name] = {
                "url": url,
                "client-id": client_id,
                "client-secrets": [client_secret],
            }
            if "default-server" not in config:
                config["default-server"] = server_name
    except ConfigWriteError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)
    print(f"\n✅ Saved connection for server '{server_name}'")
    print(f"   URL:           {url}")
    print(f"   Client ID:     {client_id}")
    print(f"   Config saved to {CONFIG_PATH}")


def register_cmd(args):
    """Register a new client on a server using admin credentials from config."""
    interactive = getattr(args, "interactive", False)

    # Server resolution: --server is mandatory
    server_name = getattr(args, "server", None)
    if not server_name:
        if not interactive:
            print("Error: --server is required. Provide --server or use --interactive.", file=sys.stderr)
            sys.exit(1)
        config = load_config()
        default_server = config.get("default-server", "") if config else ""
        prompt = f"Server name [{default_server}]: " if default_server else "Server name: "
        server_name = input(prompt).strip() or default_server
        if not server_name:
            print("Error: No server name provided.", file=sys.stderr)
            sys.exit(1)
        args.server = server_name

    server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
    if not auth_token:
        print("Error: No admin credentials found for this server.", file=sys.stderr)
        sys.exit(1)

    # New-client fields
    name = getattr(args, "name", "") or ""
    new_client_id = getattr(args, "new_client_id", None)
    new_client_secret = getattr(args, "new_client_secret", None)

    if interactive:
        if not name:
            name = input("Client name (blank for none): ").strip()
        if not new_client_id:
            new_client_id = input("New client ID (blank to auto-generate): ").strip() or None
        if not new_client_secret:
            new_client_secret = input("New client secret (blank to auto-generate): ").strip() or None

    new_client_id, new_client_secret = register_client(
        server_url,
        name,
        auth_token,
        new_client_id=new_client_id,
        new_client_secret=new_client_secret,
        ssl_context=ssl_ctx,
    )
    if new_client_id:
        print("\n   Share the credentials above with the new client.")
    sys.exit(0 if new_client_id else 1)


def list_state_servers_cmd(args):
    """List server names that have a clients database in the state dir.

    Useful when the state dir is decoupled from config (e.g. you migrated
    state, or you're running on a fresh box with only the volume mounted).
    """
    state_servers_dir = get_state_dir() / "servers"
    if not state_servers_dir.exists():
        print(f"No state dir at {state_servers_dir}")
        return
    rows = []
    for entry in sorted(state_servers_dir.iterdir()):
        if not entry.is_dir():
            continue
        path = entry / "clients.json"
        if not path.exists():
            continue
        try:
            with open(path) as f:
                clients = json.load(f)
            n = len(clients)
            admins = sum(1 for c in clients.values() if c.get("admin"))
            rows.append((entry.name, n, admins))
        except (json.JSONDecodeError, OSError):
            rows.append((entry.name, None, None))
    if not rows:
        print(f"No servers found in {state_servers_dir}")
        return
    print(f"State servers ({state_servers_dir}):")
    for name, n, admins in rows:
        if n is None:
            print(f"  {name}  (clients.json unreadable)")
        else:
            client_word = "client" if n == 1 else "clients"
            admin_word = "admin" if admins == 1 else "admins"
            print(f"  {name}  ({n} {client_word}, {admins} {admin_word})")


def fingerprint_cmd(args):
    """Print the SHA-256 of the leaf cert presented by *--server-url* (or the server from config/--server).

    Paranoid by default: requires either --ca-cert (verify the cert during the
    handshake against that CA) or --insecure (skip verification — pure TOFU).
    Without one of these, blindly pinning whatever cert appears on the wire
    would defeat the point of pinning.
    """
    global _INSECURE_WARNED

    url = getattr(args, "server_url", None)
    server_config = None
    if not url:
        # Fall back to resolving the named server's URL from config.
        try:
            url, _ = resolve_server(args)
        except SystemExit:
            url = None
        server_config = _server_config_for(args)
    if not url:
        print("Error: --server-url <https://...> or a configured server is required.", file=sys.stderr)
        sys.exit(1)
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme != "https":
        print(f"Error: fingerprint requires an https:// URL (got {url!r}).", file=sys.stderr)
        sys.exit(1)
    host = parsed.hostname
    port = parsed.port or 443
    if not host:
        print(f"Error: could not parse host from {url!r}.", file=sys.stderr)
        sys.exit(1)

    insecure = bool(_resolve_security_setting(args, server_config, "insecure", default=False))
    ca_cert = _resolve_security_setting(args, server_config, "ca-cert", default=None)

    if not insecure and not ca_cert:
        print(
            "Error: fingerprint requires either --ca-cert <path> (verify the cert against this CA)\n"
            "       or --insecure (skip verification — pure TOFU).\n"
            "       Without one, you would be blindly pinning whatever cert appears on the wire.",
            file=sys.stderr,
        )
        sys.exit(1)

    if insecure:
        if not _INSECURE_WARNED:
            print(
                "⚠️  --insecure: TLS verification disabled for this process. All certs will be accepted.",
                file=sys.stderr,
            )
            _INSECURE_WARNED = True
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    else:
        # Strict by default in create_default_context: CERT_REQUIRED + check_hostname=True.
        ctx = ssl.create_default_context(cafile=ca_cert)

    try:
        with socket.create_connection((host, port), timeout=10) as sock:
            with ctx.wrap_socket(sock, server_hostname=host) as ssock:
                der = ssock.getpeercert(binary_form=True)
    except (OSError, ssl.SSLError) as exc:
        print(f"Error: failed to connect to {host}:{port}: {exc}", file=sys.stderr)
        sys.exit(1)
    fp = hashlib.sha256(der).hexdigest()
    print(fp)


COMMAND_GROUPS = [
    ("Server", ["server", "server-setup", "server-add-user", "list-state-servers"]),
    (
        "Client",
        [
            "connect",
            "upload",
            "download",
            "list",
            "set-preview",
            "get-pad",
            "set-pad",
            "rotate",
            "complete-rotation",
            "fingerprint",
        ],
    ),
    ("Admin", ["register", "clients", "delete-client"]),
]


def _build_grouped_help(subparsers_action):
    """Build grouped help text from COMMAND_GROUPS, reading descriptions from the subparsers."""
    # Read help strings from the registered subparsers
    choices = {}
    for choice in subparsers_action._choices_actions:
        choices[choice.dest] = choice.help or ""

    # Verify groups match registered subparsers (minus "help" which is internal)
    grouped = {cmd for _, cmds in COMMAND_GROUPS for cmd in cmds}
    registered = set(choices.keys()) - {"help"}
    if grouped != registered:
        missing = registered - grouped
        extra = grouped - registered
        parts = []
        if missing:
            parts.append(f"not in COMMAND_GROUPS: {missing}")
        if extra:
            parts.append(f"not registered as subparsers: {extra}")
        raise RuntimeError(f"COMMAND_GROUPS out of sync with subparsers: {', '.join(parts)}")

    # Suppress the default flat listing now that we've read from it
    subparsers_action._choices_actions.clear()

    max_cmd = max(len(cmd) for _, cmds in COMMAND_GROUPS for cmd in cmds)
    lines = []
    for group_name, cmds in COMMAND_GROUPS:
        lines.append(f"\n{group_name}:")
        for cmd in cmds:
            lines.append(f"  {cmd:<{max_cmd}}  {choices.get(cmd, '')}")
    lines.append("\nRun 'companion.py <command> --help' for more info on a command.")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description="Companion - Simple file sharing server and client",
        usage="companion.py <command> [options]",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    subparsers = parser.add_subparsers(dest="mode", metavar="", title=None)
    # Help mode
    subparsers.add_parser("help", add_help=False)
    # Server mode
    server_parser = subparsers.add_parser("server", help="Run in server mode")
    server_parser.add_argument("--port", type=int, help="Port to listen on (default: 8080 or from config)")
    server_parser.add_argument("--server", help="Named server from config file")
    server_parser.add_argument("--debug", action="store_true", help="Enable debug logging")
    # Server setup mode
    setup_parser = subparsers.add_parser("server-setup", help="First-time server setup")
    setup_parser.add_argument("--server", help="Server name (default: 'default')")
    setup_parser.add_argument("--url", help="Server URL (required in non-interactive mode)")
    setup_parser.add_argument("--client-id", help="Admin client ID (auto-generated if blank)")
    setup_parser.add_argument("--client-secret", help="Admin client secret (auto-generated if blank)")
    setup_parser.add_argument("--client-name", default="", help="Friendly name for the admin client")
    setup_parser.add_argument("--interactive", action="store_true", help="Prompt for missing fields")
    # Server add-user mode
    add_user_parser = subparsers.add_parser("server-add-user", help="Add a user to a configured server")
    add_user_parser.add_argument("--server", help="Named server from config file")
    add_user_parser.add_argument("--client-name", default="", help="Friendly name for this client")
    add_user_parser.add_argument("--admin", action="store_true", help="Grant admin privileges")
    add_user_parser.add_argument("--client-id", help="Client ID (auto-generated if blank)")
    add_user_parser.add_argument("--client-secret", help="Client secret (auto-generated if blank)")
    add_user_parser.add_argument("--interactive", action="store_true", help="Prompt for missing fields")
    # List state servers (diagnostic: which server names have a clients DB on disk)
    subparsers.add_parser("list-state-servers", help="List server names with a clients DB in the state dir")
    # Connect mode
    connect_parser = subparsers.add_parser("connect", help="Save server connection credentials locally")
    connect_parser.add_argument("--server", help="Server name (default: 'default')")
    connect_parser.add_argument("--url", help="Server URL")
    connect_parser.add_argument("--client-id", help="Client ID")
    connect_parser.add_argument("--client-secret", help="Client secret")
    connect_parser.add_argument("--interactive", action="store_true", help="Prompt for missing fields")

    # Helper to add common server selection args to client subparsers
    def add_server_args(subparser, needs_auth=True):
        subparser.add_argument("--server", help="Named server from config file")
        subparser.add_argument("--server-url", help="Explicit server URL (e.g., http://localhost:8080)")
        if needs_auth:
            subparser.add_argument("--client-id", help="Client ID (overrides config)")
            subparser.add_argument("--client-secret", help="Client secret (overrides config)")
        # TLS security overrides (paranoid by default; see make_pinned_ssl_context).
        subparser.add_argument("--ca-cert", help="Path to a CA bundle (overrides system store)")
        subparser.add_argument("--cert-sha256", help="Pinned hex SHA-256 of the server's leaf cert")
        subparser.add_argument(
            "--insecure",
            action="store_true",
            help="Disable TLS verification (warning printed once per process)",
        )

    # Upload mode
    upload_parser = subparsers.add_parser("upload", help="Upload a file to the server")
    upload_parser.add_argument("file_path", help="Path to file to upload")
    upload_parser.add_argument(
        "--set-preview",
        action="store_true",
        help="Automatically set this file as preview for all clients after upload",
    )
    add_server_args(upload_parser, needs_auth=True)
    # List mode
    list_parser = subparsers.add_parser("list", help="List all available files")
    add_server_args(list_parser, needs_auth=True)
    # Download mode
    download_parser = subparsers.add_parser("download", help="Download a file from the server")
    download_parser.add_argument("filename", help="Name of the file to download")
    download_parser.add_argument("-o", "--output", help="Output directory (default: current directory)")
    add_server_args(download_parser, needs_auth=True)
    # Set preview mode
    preview_parser = subparsers.add_parser("set-preview", help="Set the current preview for all clients")
    preview_parser.add_argument("filename", help="Filename to preview")
    add_server_args(preview_parser, needs_auth=True)
    # Get pad mode
    get_pad_parser = subparsers.add_parser("get-pad", help="Get the current pad content")
    add_server_args(get_pad_parser, needs_auth=True)
    # Set pad mode
    set_pad_parser = subparsers.add_parser("set-pad", help="Set the pad content")
    set_pad_parser.add_argument("content", help="Content to set in the pad")
    add_server_args(set_pad_parser, needs_auth=True)
    # Register mode
    register_parser = subparsers.add_parser("register", help="Register a new client with the server")
    register_parser.add_argument("--name", default="", help="Friendly name for this client")
    register_parser.add_argument("--new-client-id", help="Client ID for the new client (auto-generated if blank)")
    register_parser.add_argument(
        "--new-client-secret", help="Client secret for the new client (auto-generated if blank)"
    )
    register_parser.add_argument("--interactive", action="store_true", help="Prompt for missing fields")
    add_server_args(register_parser, needs_auth=True)
    # Clients mode
    clients_parser = subparsers.add_parser("clients", help="List registered clients on the server")
    add_server_args(clients_parser, needs_auth=True)
    # Delete client mode
    delete_client_parser = subparsers.add_parser("delete-client", help="Delete a registered client (admin only)")
    delete_client_parser.add_argument("client_id_to_delete", help="Client ID to delete")
    add_server_args(delete_client_parser, needs_auth=True)
    # Rotate mode
    rotate_parser = subparsers.add_parser("rotate", help="Rotate your client credentials")
    add_server_args(rotate_parser, needs_auth=True)
    # Complete rotation mode
    complete_rotation_parser = subparsers.add_parser("complete-rotation", help="Complete an interrupted rotation")
    add_server_args(complete_rotation_parser, needs_auth=True)
    # Fingerprint mode: print the server's leaf cert SHA-256 (for pinning)
    fingerprint_parser = subparsers.add_parser(
        "fingerprint", help="Print SHA-256 of the server's leaf cert (for cert-sha256 pinning)"
    )
    fingerprint_parser.add_argument("--server", help="Named server from config (uses its url)")
    fingerprint_parser.add_argument("--server-url", help="Explicit https:// URL to fingerprint")
    fingerprint_parser.add_argument("--ca-cert", help="CA bundle to verify the cert against during fingerprint")
    fingerprint_parser.add_argument(
        "--insecure", action="store_true", help="Skip verification (pure TOFU; warning printed once)"
    )
    # Build grouped help and attach as epilog
    parser.epilog = _build_grouped_help(subparsers)
    # Remove the empty positional arguments section from output
    parser._action_groups = [g for g in parser._action_groups if g.title is not None]

    # Parse args
    args = parser.parse_args()
    if not args.mode or args.mode == "help":
        parser.print_help()
        sys.exit(0 if args.mode == "help" else 1)
    if args.mode == "server-setup":
        server_setup_cmd(args)
    elif args.mode == "server-add-user":
        server_add_user_cmd(args)
    elif args.mode == "list-state-servers":
        list_state_servers_cmd(args)
    elif args.mode == "connect":
        connect_cmd(args)
    elif args.mode == "server":
        # Configure logging
        log_level = logging.DEBUG if args.debug else logging.INFO
        logging.basicConfig(
            level=log_level,
            format="[%(asctime)s] %(levelname)s: %(message)s",
            datefmt="%Y-%m-%d %H:%M:%S",
        )
        port = resolve_server_config(args)
        run_server(port)
    elif args.mode == "upload":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required for upload.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        success = upload_file(
            server_url,
            args.file_path,
            auth_token,
            set_preview=args.set_preview,
            ssl_context=ssl_ctx,
        )
        sys.exit(0 if success else 1)
    elif args.mode == "list":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required to list files.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        success = list_files(server_url, auth_token, ssl_context=ssl_ctx)
        sys.exit(0 if success else 1)
    elif args.mode == "download":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required to download files.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        success = download_file(server_url, args.filename, auth_token, args.output, ssl_context=ssl_ctx)
        sys.exit(0 if success else 1)
    elif args.mode == "set-preview":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required for set-preview.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        file_id = resolve_file_id(server_url, args.filename, auth_token, ssl_context=ssl_ctx)
        if not file_id:
            print(f"Error: File not found on server: {args.filename}", file=sys.stderr)
            sys.exit(1)
        success = set_preview_func(server_url, file_id, auth_token, ssl_context=ssl_ctx)
        sys.exit(0 if success else 1)
    elif args.mode == "get-pad":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required to get pad.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        success = get_pad(server_url, auth_token, ssl_context=ssl_ctx)
        sys.exit(0 if success else 1)
    elif args.mode == "set-pad":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required for set-pad.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        success = set_pad(server_url, args.content, auth_token, ssl_context=ssl_ctx)
        sys.exit(0 if success else 1)
    elif args.mode == "register":
        register_cmd(args)
    elif args.mode == "clients":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required to list clients.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        success = list_clients_cmd(server_url, auth_token, ssl_context=ssl_ctx)
        sys.exit(0 if success else 1)
    elif args.mode == "delete-client":
        server_url, auth_token, ssl_ctx = resolve_server_and_ssl(args)
        if not auth_token:
            print("Error: Credentials required to delete a client.", file=sys.stderr)
            print("Run 'companion server-add-user' first, or provide --client-id and --client-secret.", file=sys.stderr)
            sys.exit(1)
        success = delete_client_cmd(server_url, args.client_id_to_delete, auth_token, ssl_context=ssl_ctx)
        sys.exit(0 if success else 1)
    elif args.mode == "rotate":
        rotate_cmd(args)
    elif args.mode == "complete-rotation":
        complete_rotation_cmd(args)
    elif args.mode == "fingerprint":
        fingerprint_cmd(args)


if __name__ == "__main__":
    # Force UTF-8 encoding on Windows for emoji support
    if sys.platform == "win32":
        import codecs

        sys.stdout = codecs.getwriter("utf-8")(sys.stdout.detach())
        sys.stderr = codecs.getwriter("utf-8")(sys.stderr.detach())
    main()
